package com.kaipai.service.ai.profileimport;
import com.fasterxml.jackson.databind.*; import java.util.*;
public class ProfileImportSchemaValidator { private final ObjectMapper mapper=new ObjectMapper(); private static final Set<String> PROFILE_FIELDS=Set.of("gender","public_name","age","height","weight","origin_place","school_name","major_name","language_tags","specialty_tags","role_type_tags","professional_ability_tags","intro"); public ValidatedExtraction validate(String json){try{JsonNode root=mapper.readTree(json);List<Candidate> candidates=new ArrayList<>();for(JsonNode item:root.path("profileCandidates")){String field=item.path("fieldKey").asText();if(!PROFILE_FIELDS.contains(field))throw new IllegalArgumentException("unknown field");String value=item.path("candidateValue").asText();String sourceType=item.path("sourceType").asText("direct");boolean inferred="inferred_from_roles".equals(sourceType);candidates.add(new Candidate(field,value,!inferred,!inferred,inferred));}return new ValidatedExtraction(candidates);}catch(Exception e){if(e instanceof IllegalArgumentException)throw (IllegalArgumentException)e;throw new IllegalArgumentException("invalid extraction",e);}} public record Candidate(String fieldKey,String value,boolean selected,boolean confirmed,boolean requiresExplicitConfirmation){} public record ValidatedExtraction(List<Candidate> profileCandidates){public Candidate profileCandidate(String key){return profileCandidates.stream().filter(c->c.fieldKey().equals(key)).findFirst().orElseThrow();}}}
